import React, { useState } from 'react';
import Home from './pages/Home';
import Game from './pages/Game';
import About from './pages/About';
import Settings from './pages/Settings'; // Importa o novo componente
import Layout from './components/Layout';
import './styles/globals.css';

function App() {
  const [view, setView] = useState('home'); 
  const [gameMode, setGameMode] = useState(null);
  
  // Estado das Definições
  const [settings, setSettings] = useState({
    darkMode: true,
    animations: true,
    explicit: true,
    language: 'PT-PT' // Valor inicial
  });

  const handleStartGame = (modeId) => {
    setGameMode(modeId);
    setView('game');
  };

  const handleBackToHome = () => {
    setView('home');
    setGameMode(null);
  };

  const handleUpdateSetting = (key, value) => {
    setSettings(prev => ({ ...prev, [key]: value }));
  };

  return (
    <Layout onOpenSettings={() => setView('settings')}>
      {view === 'home' && (
        <div className="animate-in fade-in duration-500">
          <Home onNavigate={handleStartGame} />
        </div>
      )}
      
      {view === 'game' && (
        <div className="animate-in slide-in-from-right duration-500">
          <Game modeId={gameMode} onBack={handleBackToHome} />
        </div>
      )}

      {view === 'about' && (
        <div className="animate-in slide-in-from-bottom duration-500">
          <About onBack={() => setView('home')} />
        </div>
      )}

      {/* Vista de Definições */}
      {view === 'settings' && (
        <div className="animate-in slide-in-from-top duration-500">
          <Settings 
            settings={settings} 
            onUpdate={handleUpdateSetting} 
            onBack={() => setView('home')} 
          />
        </div>
      )}

      {/* Botão flutuante para o About na Home */}
      {view === 'home' && (
        <button 
          onClick={() => setView('about')}
          className="fixed bottom-8 left-8 text-[10px] text-raw-bone/40 hover:text-raw-cyan uppercase tracking-widest font-bold rotate-90 origin-left z-50 transition-colors"
        >
          About RAW.
        </button>
      )}

      {/* Botão flutuante para Settings na Home (Opcional, se não usares no Header) */}
      {view === 'home' && (
        <button 
          onClick={() => setView('settings')}
          className="fixed top-24 right-8 text-[10px] text-raw-bone/40 hover:text-raw-cyan uppercase tracking-widest font-bold -rotate-90 origin-right z-50 transition-colors"
        >
          Settings
        </button>
      )}
    </Layout>
  );
}

export default App;
